        colAction.setCellFactory(param -> new TableCell<ChiTietHoaDonDTO, Void>() {
            private final Button btnDelete = new Button("️");
            {
                btnDelete.setStyle("-fx-font-size: 11px; -fx-padding: 3 8;");
                btnDelete.setOnAction(event -> {
