    // ============================================================
    // Data Loading Methods
    // ============================================================

    /**
     * Tải dữ liệu Phiếu Đặt
     */
    private void loadPhieuDatData() {
        Task<List<PhieuDatPhongDTO>> task = new Task<>() {
            @Override
            protected List<PhieuDatPhongDTO> call() {
                try {
                    List<PhieuDatPhongDTO> all = phieuDatPhongService.getAllPhieuDatPhong();
                    String keyword = txtSearchPhieu.getText() != null ? txtSearchPhieu.getText().trim().toLowerCase() : "";
                    String status = cbTrangThaiPhieu.getValue();
                    LocalDate from = dpFromDate.getValue();
                    LocalDate to = dpToDate.getValue();

                    return all.stream()
                            .filter(p -> keyword.isEmpty() ||
                                    (p.getMaPhieu() != null && p.getMaPhieu().toLowerCase().contains(keyword)) ||
                                    (p.getMaKhachHang() != null && p.getMaKhachHang().toLowerCase().contains(keyword)))
                            .filter(p -> "Tất cả".equals(status) || (p.getTrangThai() != null && p.getTrangThai().equals(status)))
                            .filter(p -> p.getNgayNhan() != null && !p.getNgayNhan().isBefore(from) && !p.getNgayNhan().isAfter(to))
                            .collect(Collectors.toList());
                } catch (Exception e) {
                    e.printStackTrace();
                    return new java.util.ArrayList<>();
                }
            }
        };

        task.setOnSucceeded(evt -> {
            List<PhieuDatPhongDTO> data = task.getValue();
            tvPhieuDat.getItems().setAll(data);
            updateStatPhieu(data);
        });

        task.setOnFailed(evt -> {
            System.err.println("Lỗi tải phiếu đặt");
        });

        Thread t = new Thread(task);
        t.setDaemon(true);
        t.start();
    }

    /**
     * Cập nhật stat cards
     */
    private void updateStatPhieu(List<PhieuDatPhongDTO> data) {
        lblTotalPhieu.setText(String.valueOf(data.size()));
        long waiting = data.stream().filter(p -> "Đang chờ".equals(p.getTrangThai())).count();
        long confirmed = data.stream().filter(p -> "Đã xác nhận".equals(p.getTrangThai())).count();
        lblWaitingPhieu.setText(String.valueOf(waiting));
        lblConfirmedPhieu.setText(String.valueOf(confirmed));
    }

    /**
     * Tải danh sách Phiếu Đặt cho checkout
     */
    private void loadPhieuDatForCheckout() {
        Task<List<String>> task = new Task<>() {
            @Override
            protected List<String> call() {
                try {
                    return phieuDatPhongService.getAllPhieuDatPhong().stream()
                            .filter(p -> "Đã checkin".equals((p.getTrangThai())))
                            .map(p -> p.getMaPhieu() + " - " + (p.getMaKhachHang() != null ? p.getMaKhachHang() : "N/A"))
                            .collect(Collectors.toList());
                } catch (Exception e) {
                    return new java.util.ArrayList<>();
                }
            }
        };

        task.setOnSucceeded(evt -> {
            List<String> items = task.getValue();
            cbPhieuDatCheckout.getItems().setAll(items);
        });

        Thread t = new Thread(task);
        t.setDaemon(true);
        t.start();
    }

    /**
     * Tải thông tin checkout
     */
    private void loadCheckoutInfo() {
        String selected = cbPhieuDatCheckout.getValue();
        if (selected == null || selected.isEmpty()) {
            showAlert("Thông báo", "Vui lòng chọn phiếu đặt");
            return;
        }

        String maPhieu = selected.split(" - ")[0];
        try {
            PhieuDatPhongDTO phieu = phieuDatPhongService.getPhieuDatPhongById(maPhieu);
            if (phieu != null) {
                // Update guest info - using ma instead of ten
                lblGuestNameCheckout.setText(phieu.getMaKhachHang() != null ? phieu.getMaKhachHang() : "—");
                lblRoomCheckout.setText(phieu.getMaPhong() != null ? phieu.getMaPhong() : "—");
                lblCheckInDateCheckout.setText(phieu.getNgayNhan() != null ? phieu.getNgayNhan().toString() : "—");
                lblCheckOutDateCheckout.setText(phieu.getNgayTra() != null ? phieu.getNgayTra().toString() : "—");

                if (phieu.getNgayNhan() != null && phieu.getNgayTra() != null) {
                    long days = ChronoUnit.DAYS.between(phieu.getNgayNhan(), phieu.getNgayTra());
                    lblNumDaysCheckout.setText(String.valueOf(days));

                    // Get room price
                    if (phieu.getMaPhong() != null) {
                        PhongDTO room = phongService.getPhongById(phieu.getMaPhong());
                        if (room != null) {
                            double price = room.getGiaPhong();
                            lblRoomPriceCheckout.setText(String.format("%,.0f đ", price));
                            double roomTotal = price * days;
                            lblRoomTotalCheckout.setText(String.format("%,.0f đ", roomTotal));
                        }
                    }
                }

                // Load service details (placeholder)
                tvServiceDetails.getItems().clear();
            }
        } catch (Exception e) {
            e.printStackTrace();
            showAlert("Lỗi", "Không thể tải thông tin phiếu đặt");
        }
    }

     /**
      * Xử lý thanh toán & trả phòng
      */
     private void processCheckout() {
         String selected = cbPhieuDatCheckout.getValue();
         if (selected == null || selected.isEmpty()) {
             showAlert("Lỗi", "Vui lòng chọn phiếu đặt");
             return;
         }

         // Validate and process payment
         Alert confirm = new Alert(Alert.AlertType.CONFIRMATION);
         confirm.setTitle("Xác Nhận Trả Phòng");
         confirm.setHeaderText(null);
         confirm.setContentText("Bạn có chắc chắn muốn hoàn tất trả phòng và thanh toán?");

         Optional<ButtonType> result = confirm.showAndWait();
         if (result.isPresent() && result.get() == ButtonType.OK) {
             processCheckoutReal();
         }
     }

     /**
      * Xử lý trả phòng thực tế
      */
     private void processCheckoutReal() {
         try {
             String selected = cbPhieuDatCheckout.getValue();
             String maPhieu = selected.split(" - ")[0];
             PhieuDatPhongDTO phieu = phieuDatPhongService.getPhieuDatPhongById(maPhieu);

             if (phieu == null) {
                 showAlert("Lỗi", "Không tìm thấy phiếu đặt");
                 return;
             }

             // Tính toán hóa đơn
             PhongDTO phong = phongService.getPhongById(phieu.getMaPhong());
             if (phong == null) {
                 showAlert("Lỗi", "Không tìm thấy phòng");
                 return;
             }

             // Tính số ngày
             long numDays = ChronoUnit.DAYS.between(phieu.getNgayNhan(), phieu.getNgayTra());
             if (numDays <= 0) numDays = 1;

             // Tính tiền phòng
             double giaPhong = phong.getGiaPhong();
             double tongTienPhong = giaPhong * numDays;

             // Lấy dịch vụ dari database
             List<HoaDonDTO> hoaDons = hoaDonService.getHoaDonByPhieuDat(maPhieu);
             double tongTienDichVu = 0;
             for (HoaDonDTO hd : hoaDons) {
                 tongTienDichVu += hd.getTongTienDichVu();
             }

             // Lấy VAT và chiết khấu từ UI
             double vat = spinnerVAT.getValue() != null ? spinnerVAT.getValue() : 0;
             double chietKhau = spinnerDiscount.getValue() != null ? spinnerDiscount.getValue() : 0;

             // Tính tổng tiền
             double tienVAT = tongTienPhong * (vat / 100);
             double tongTien = tongTienPhong + tongTienDichVu + tienVAT - chietKhau;

             // Tạo hoá đơn mới
             HoaDonDTO hoaDon = new HoaDonDTO();
             hoaDon.setMaKhachHang(phieu.getMaKhachHang());
             hoaDon.setMaNhanVien(currentUser.getTaiKhoan());
             hoaDon.setNgayLap(LocalDate.now());
             hoaDon.setTongTienPhong(tongTienPhong);
             hoaDon.setTongTienDichVu(tongTienDichVu);
             hoaDon.setThueVAT(tienVAT);
             hoaDon.setChietKhau(chietKhau);
             hoaDon.setTongTien(tongTien);
             hoaDon.setTrangThaiThanhToan("Đã Thanh Toán");
             hoaDon.setMaPhongDat(phieu.getMaPhong());
             hoaDon.setTenPhong(phong.getTenPhong());

             // Lưu hoá đơn
             hoaDonService.addHoaDon(hoaDon);

             // Cập nhật trạng thái phiếu đặt
             phieu.setTrangThai("Trả Phòng");
             phieuDatPhongService.updatePhieuDatPhong(phieu);

             // Cập nhật trạng thái phòng về "Trống"
             phong.setTinhTrang("Trống");
             phongService.updatePhong(phong);

             showAlert("Thành Công", String.format("Trả phòng thành công!\nTổng tiền: %,.0f đ", tongTien));
             clearCheckoutForm();
             loadPhieuDatForCheckout();

         } catch (Exception e) {
             e.printStackTrace();
             showAlert("Lỗi", "Lỗi khi xử lý trả phòng: " + e.getMessage());
         }
     }

     /**
      * Xử lý nhận phòng (Check-in) từ phiếu đã đặt
      */
     public boolean processCheckIn(String maPhieu) {
         try {
             PhieuDatPhongDTO phieu = phieuDatPhongService.getPhieuDatPhongById(maPhieu);
             if (phieu == null) {
                 showAlert("Lỗi", "Không tìm thấy phiếu đặt");
                 return false;
             }

             // Cập nhật trạng thái phiếu đặt
             phieu.setTrangThai("Nhận Phòng");
             phieuDatPhongService.updatePhieuDatPhong(phieu);

             // Cập nhật trạng thái phòng
             PhongDTO phong = phongService.getPhongById(phieu.getMaPhong());
             if (phong != null) {
                 phong.setTinhTrang("Đang ở");
                 phongService.updatePhong(phong);
             }

             showAlert("Thành Công", "Khách đã nhận phòng thành công!");
             return true;

         } catch (Exception e) {
             e.printStackTrace();
             showAlert("Lỗi", "Lỗi khi xử lý nhận phòng: " + e.getMessage());
             return false;
         }
     }

     /**
      * Xử lý đặt phòng mới (booking)
      */
     public boolean processBooking(String maKhachHang, String maPhong, LocalDate ngayNhan, LocalDate ngayTra) {
         try {
             if (maKhachHang == null || maKhachHang.isEmpty() || maPhong == null) {
                 showAlert("Lỗi", "Vui lòng nhập đầy đủ thông tin");
                 return false;
             }

             // Kiểm tra phòng có sẵn không
             PhongDTO phong = phongService.getPhongById(maPhong);
             if (phong == null) {
                 showAlert("Lỗi", "Phòng không tồn tại");
                 return false;
             }

             if (!phong.getTinhTrang().equalsIgnoreCase("Trống")) {
                 showAlert("Lỗi", "Phòng không có sẵn");
                 return false;
             }

             // Tính tổng tiền
             long numDays = ChronoUnit.DAYS.between(ngayNhan, ngayTra);
             if (numDays <= 0) numDays = 1;
             double tongTien = phong.getGiaPhong() * numDays;

             // Tạo phiếu đặt phòng mới
             PhieuDatPhongDTO phieu = new PhieuDatPhongDTO();
             phieu.setMaKhachHang(maKhachHang);
             phieu.setMaPhong(maPhong);
             phieu.setNgayDat(LocalDate.now());
             phieu.setNgayNhan(ngayNhan);
             phieu.setNgayTra(ngayTra);
             phieu.setTongTien(tongTien);
             phieu.setTrangThai("Đặt Phòng");
             phieu.setMaNhanVien(currentUser.getTaiKhoan());

             // Lưu phiếu đặt phòng
             PhieuDatPhongDTO result = phieuDatPhongService.addPhieuDatPhong(phieu);
             if (result == null) {
                 showAlert("Lỗi", "Không thể tạo phiếu đặt phòng");
                 return false;
             }

             // Cập nhật trạng thái phòng
             phong.setTinhTrang("Đã Đặt");
             phongService.updatePhong(phong);

             showAlert("Thành Công", String.format("Đặt phòng thành công!\nMã phiếu: %s\nTổng tiền: %,.0f đ", result.getMaPhieu(), tongTien));
             return true;

         } catch (Exception e) {
             e.printStackTrace();
             showAlert("Lỗi", "Lỗi khi đặt phòng: " + e.getMessage());
             return false;
         }
     }

     /**
      * Xử lý hủy phiếu đặt phòng
      */
     public boolean cancelBooking(String maPhieu) {
         try {
             PhieuDatPhongDTO phieu = phieuDatPhongService.getPhieuDatPhongById(maPhieu);
             if (phieu == null) {
                 showAlert("Lỗi", "Không tìm thấy phiếu đặt");
                 return false;
             }

             // Xác nhận hủy
             Alert confirm = new Alert(Alert.AlertType.CONFIRMATION);
             confirm.setTitle("Xác Nhận Hủy");
             confirm.setHeaderText(null);
             confirm.setContentText("Bạn có chắc chắn muốn hủy phiếu đặt phòng?");

             Optional<ButtonType> result = confirm.showAndWait();
             if (result.isPresent() && result.get() == ButtonType.OK) {
                 // Cập nhật trạng thái
                 phieu.setTrangThai("Hủy");
                 phieuDatPhongService.updatePhieuDatPhong(phieu);

                 // Cập nhật trạng thái phòng
                 PhongDTO phong = phongService.getPhongById(phieu.getMaPhong());
                 if (phong != null) {
                     phong.setTinhTrang("Trống");
                     phongService.updatePhong(phong);
                 }

                 showAlert("Thành Công", "Phiếu đặt phòng đã được hủy");
                 return true;
             }
             return false;

         } catch (Exception e) {
             e.printStackTrace();
             showAlert("Lỗi", "Lỗi khi hủy phiếu đặt: " + e.getMessage());
             return false;
         }
     }

     /**
      * Xử lý hoàn thành bảo trì
      */
     public boolean completeMaintenance(String maPhong) {
         try {
             PhongDTO phong = phongService.getPhongById(maPhong);
             if (phong == null) {
                 showAlert("Lỗi", "Không tìm thấy phòng");
                 return false;
             }

             // Xác nhận hoàn thành
             Alert confirm = new Alert(Alert.AlertType.CONFIRMATION);
             confirm.setTitle("Xác Nhận");
             confirm.setHeaderText(null);
             confirm.setContentText("Bạn có chắc chắn phòng đã hoàn thành bảo trì?");

             Optional<ButtonType> result = confirm.showAndWait();
             if (result.isPresent() && result.get() == ButtonType.OK) {
                 // Cập nhật trạng thái phòng về Trống
                 phong.setTinhTrang("Trống");
                 phongService.updatePhong(phong);

                 showAlert("Thành Công", "Phòng đã hoàn thành bảo trì");
                 return true;
             }
             return false;

         } catch (Exception e) {
             e.printStackTrace();
             showAlert("Lỗi", "Lỗi khi hoàn thành bảo trì: " + e.getMessage());
             return false;
         }
     }

    /**
     * Xóa form checkout
     */
    private void clearCheckoutForm() {
        cbPhieuDatCheckout.setValue(null);
        lblGuestNameCheckout.setText("—");
        lblRoomCheckout.setText("—");
        lblCheckInDateCheckout.setText("—");
        lblCheckOutDateCheckout.setText("—");
        lblNumDaysCheckout.setText("0");
        lblRoomPriceCheckout.setText("—");
        lblRoomTotalCheckout.setText("0 đ");
        lblServiceTotalCheckout.setText("0 đ");
        lblVATCheckout.setText("0 đ");
        lblDiscountCheckout.setText("0 đ");
        lblGrandTotalCheckout.setText("0 đ");
        tvServiceDetails.getItems().clear();
        cbPaymentMethod.setValue("Tiền Mặt");
    }

    /**
     * Hiển thị dialog
     */
    private void showAlert(String title, String message) {
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setTitle(title);
        alert.setHeaderText(null);
        alert.setContentText(message);
        alert.showAndWait();
    }
}

package iuh.fit.presentation.controller;

import iuh.fit.core.dto.HoaDonDTO;
import iuh.fit.core.service.IHoaDonService;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.chart.BarChart;
import javafx.scene.chart.CategoryAxis;
import javafx.scene.chart.NumberAxis;
import javafx.scene.chart.XYChart;
import javafx.scene.control.*;
import javafx.scene.effect.DropShadow;
import javafx.scene.layout.*;
import javafx.scene.paint.Color;
import javafx.scene.text.Font;
import javafx.scene.text.FontWeight;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.*;
import java.util.stream.Collectors;

public class RevenueController {

    private final IHoaDonService hoaDonService;

    // UI Components
    private DatePicker dpStartDate;
    private DatePicker dpEndDate;
    private Label lblTotalRevenue;
    private Label lblTotalInvoices;
    private Label lblAverageInvoice;
    private Label lblServiceRevenue;
    private TableView<HoaDonDTO> tvHoaDon;
    private BarChart<String, Number> chartRevenue;

    // Colors
    private final String COLOR_PRIMARY = "#0066cc";
    private final String COLOR_ACCENT = "#17a2b8";
    private final String COLOR_TEXT_MAIN = "#0f172a";
    private final String COLOR_TEXT_MUTED = "#64748b";
    private final String COLOR_BG_LIGHT = "#f8fafc";
    private final String COLOR_SUCCESS = "#10b981";

    public RevenueController(IHoaDonService hoaDonService) {
        this.hoaDonService = hoaDonService;
    }

    public BorderPane createRevenueView() {
        BorderPane root = new BorderPane();
        root.setStyle("-fx-background-color: " + COLOR_BG_LIGHT + ";");

        // Top: Title bar
        VBox topArea = new VBox(12);
        topArea.setPadding(new Insets(20, 25, 0, 25));
        topArea.getChildren().add(createTitleBar());
        root.setTop(topArea);

        // Center: Main content
        VBox centerArea = new VBox(15);
        centerArea.setPadding(new Insets(20, 25, 25, 25));
        centerArea.getChildren().addAll(
                createFilterBar(),
                createStatCardsRow(),
                createRevenueChartCard(),
                createInvoiceTableCard()
        );
        ScrollPane scrollPane = new ScrollPane(centerArea);
        scrollPane.setFitToWidth(true);
        scrollPane.setStyle("-fx-background-color: transparent; -fx-control-inner-background: transparent;");
        root.setCenter(scrollPane);

        // Load initial data
        loadRevenueData();

        return root;
    }

    private VBox createTitleBar() {
        VBox vbox = new VBox(3);
        Label title = new Label(" Thống Kê Doanh Thu");
        title.setFont(Font.font("Segoe UI", FontWeight.EXTRA_BOLD, 24));
        title.setTextFill(Color.web(COLOR_TEXT_MAIN));

        Label subtitle = new Label("Xem báo cáo doanh thu từ các hóa đơn khách sạn");
        subtitle.setFont(Font.font("Segoe UI", FontWeight.NORMAL, 13));
        subtitle.setTextFill(Color.web(COLOR_TEXT_MUTED));

        vbox.getChildren().addAll(title, subtitle);
        return vbox;
    }

    private HBox createFilterBar() {
        HBox card = new HBox(15);
        card.setAlignment(Pos.CENTER_LEFT);
        card.setPadding(new Insets(14, 16, 14, 16));
        card.setStyle("-fx-background-color: white; -fx-background-radius: 10; -fx-border-color: #e2e8f0; -fx-border-radius: 10;");
        applyCardStyle((VBox) new VBox());

        Label lblStart = new Label("Từ ngày:");
        lblStart.setStyle("-fx-font-weight: bold;");
        dpStartDate = new DatePicker(LocalDate.now().minusMonths(1));
        dpStartDate.setStyle("-fx-font-size: 12px;");

        Label lblEnd = new Label("Đến ngày:");
        lblEnd.setStyle("-fx-font-weight: bold;");
        dpEndDate = new DatePicker(LocalDate.now());
        dpEndDate.setStyle("-fx-font-size: 12px;");

        Button btnSearch = new Button(" Tìm Kiếm");
        btnSearch.setStyle("-fx-background-color: " + COLOR_PRIMARY + "; -fx-text-fill: white; -fx-font-weight: bold; -fx-padding: 8 16; -fx-background-radius: 6;");
        btnSearch.setOnAction(e -> loadRevenueData());

        Button btnExport = new Button(" Xuất Excel");
        btnExport.setStyle("-fx-background-color: " + COLOR_SUCCESS + "; -fx-text-fill: white; -fx-font-weight: bold; -fx-padding: 8 16; -fx-background-radius: 6;");
        btnExport.setOnAction(e -> showAlert("Thông báo", "Chức năng xuất Excel sẽ được bổ sung sau"));

        Region spacer = new Region();
        HBox.setHgrow(spacer, Priority.ALWAYS);

        card.getChildren().addAll(lblStart, dpStartDate, lblEnd, dpEndDate, btnSearch, spacer, btnExport);
        return card;
    }

    private HBox createStatCardsRow() {
        HBox row = new HBox(15);
        row.setAlignment(Pos.CENTER_LEFT);

        VBox c1 = makeStatCard("Tổng Doanh Thu", "0 đ", "#3b82f6", "#1d4ed8");
        VBox c2 = makeStatCard("Số Hóa Đơn", "0", "#10b981", "#047857");
        VBox c3 = makeStatCard("Hóa Đơn Trung Bình", "0 đ", "#f59e0b", "#b45309");
        VBox c4 = makeStatCard("Doanh Thu Dịch Vụ", "0 đ", "#8b5cf6", "#6d28d9");

        lblTotalRevenue = (Label) c1.getChildren().get(1);
        lblTotalInvoices = (Label) c2.getChildren().get(1);
        lblAverageInvoice = (Label) c3.getChildren().get(1);
        lblServiceRevenue = (Label) c4.getChildren().get(1);

        HBox.setHgrow(c1, Priority.ALWAYS);
        HBox.setHgrow(c2, Priority.ALWAYS);
        HBox.setHgrow(c3, Priority.ALWAYS);
        HBox.setHgrow(c4, Priority.ALWAYS);

        row.getChildren().addAll(c1, c2, c3, c4);
        return row;
    }

    private VBox createRevenueChartCard() {
        VBox card = new VBox(12);
        card.setPadding(new Insets(16));
        card.setStyle("-fx-background-color: white; -fx-background-radius: 10; -fx-border-color: #e2e8f0; -fx-border-radius: 10;");
        applyCardStyle(card);

        Label lblTitle = new Label(" Biểu Đồ Doanh Thu Theo Ngày");
        lblTitle.setFont(Font.font("Segoe UI", FontWeight.BOLD, 14));
        lblTitle.setTextFill(Color.web(COLOR_TEXT_MAIN));

        CategoryAxis xAxis = new CategoryAxis();
        NumberAxis yAxis = new NumberAxis();
        yAxis.setLabel("Doanh Thu (₫)");

        chartRevenue = new BarChart<>(xAxis, yAxis);
        chartRevenue.setTitle("Doanh Thu Theo Ngày");
        chartRevenue.setPrefHeight(350);

        card.getChildren().addAll(lblTitle, chartRevenue);
        VBox.setVgrow(chartRevenue, Priority.ALWAYS);
        return card;
    }

    private VBox createInvoiceTableCard() {
        VBox card = new VBox(12);
        card.setPadding(new Insets(16));
        card.setStyle("-fx-background-color: white; -fx-background-radius: 10; -fx-border-color: #e2e8f0; -fx-border-radius: 10;");
        applyCardStyle(card);

        Label lblTitle = new Label(" Danh Sách Hóa Đơn");
        lblTitle.setFont(Font.font("Segoe UI", FontWeight.BOLD, 14));
        lblTitle.setTextFill(Color.web(COLOR_TEXT_MAIN));

        tvHoaDon = new TableView<>();
        tvHoaDon.setPrefHeight(300);
        tvHoaDon.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_LAST);

        TableColumn<HoaDonDTO, String> colMa = new TableColumn<>("Mã HĐ");
        colMa.setCellValueFactory(param -> new javafx.beans.property.SimpleStringProperty(param.getValue().getMaHoaDon()));

        TableColumn<HoaDonDTO, LocalDate> colNgay = new TableColumn<>("Ngày Lập");
        colNgay.setCellValueFactory(param -> new javafx.beans.property.SimpleObjectProperty<>(param.getValue().getNgayLap()));

        TableColumn<HoaDonDTO, Double> colTienPhong = new TableColumn<>("Tiền Phòng");
        colTienPhong.setCellValueFactory(param -> new javafx.beans.property.SimpleObjectProperty<>(param.getValue().getTongTienPhong()));
        colTienPhong.setCellFactory(col -> new TableCell<HoaDonDTO, Double>() {
            @Override
            protected void updateItem(Double item, boolean empty) {
                super.updateItem(item, empty);
                setText(empty ? "" : String.format("%,.0f", item) + " đ");
            }
        });

        TableColumn<HoaDonDTO, Double> colTienDV = new TableColumn<>("Tiền DV");
        colTienDV.setCellValueFactory(param -> new javafx.beans.property.SimpleObjectProperty<>(param.getValue().getTongTienDichVu()));
        colTienDV.setCellFactory(col -> new TableCell<HoaDonDTO, Double>() {
            @Override
            protected void updateItem(Double item, boolean empty) {
                super.updateItem(item, empty);
                setText(empty ? "" : String.format("%,.0f", item) + " đ");
            }
        });

        TableColumn<HoaDonDTO, Double> colTong = new TableColumn<>("Tổng Tiền");
        colTong.setCellValueFactory(param -> new javafx.beans.property.SimpleObjectProperty<>(param.getValue().getTongTien()));
        colTong.setCellFactory(col -> new TableCell<HoaDonDTO, Double>() {
            @Override
            protected void updateItem(Double item, boolean empty) {
                super.updateItem(item, empty);
                setText(empty ? "" : String.format("%,.0f", item) + " đ");
                setStyle("-fx-text-fill: #0066cc; -fx-font-weight: bold;");
            }
        });

        TableColumn<HoaDonDTO, String> colStatus = new TableColumn<>("Trạng Thái");
        colStatus.setCellValueFactory(param -> new javafx.beans.property.SimpleStringProperty(param.getValue().getTrangThaiThanhToan()));

        tvHoaDon.getColumns().addAll(colMa, colNgay, colTienPhong, colTienDV, colTong, colStatus);

        card.getChildren().addAll(lblTitle, tvHoaDon);
        VBox.setVgrow(tvHoaDon, Priority.ALWAYS);
        return card;
    }

    private VBox makeStatCard(String label, String value, String colorStart, String colorEnd) {
        VBox card = new VBox(4);
        card.setPadding(new Insets(14));
        card.setStyle("-fx-background-color: linear-gradient(to bottom right, " + colorStart + ", " + colorEnd + "); -fx-background-radius: 10; -fx-border-radius: 10;");

        DropShadow shadow = new DropShadow();
        shadow.setColor(Color.color(0, 0, 0, 0.06));
        shadow.setRadius(8);
        shadow.setOffsetY(3);
        card.setEffect(shadow);

        Label lbl = new Label(label);
        lbl.setFont(Font.font("Segoe UI", FontWeight.BOLD, 11));
        lbl.setTextFill(Color.web("#ffffff", 0.85));

        Label val = new Label(value);
        val.setFont(Font.font("Segoe UI", FontWeight.EXTRA_BOLD, 24));
        val.setTextFill(Color.WHITE);

        card.getChildren().addAll(lbl, val);
        return card;
    }

    private void loadRevenueData() {
        try {
            LocalDate startDate = dpStartDate.getValue() != null ? dpStartDate.getValue() : LocalDate.now().minusMonths(1);
            LocalDate endDate = dpEndDate.getValue() != null ? dpEndDate.getValue() : LocalDate.now();

            // Get invoices
            List<HoaDonDTO> hoaDons = hoaDonService.getHoaDonByDateRange(startDate, endDate);

            // Update stat cards
            double totalRevenue = hoaDons.stream().mapToDouble(HoaDonDTO::getTongTien).sum();
            int totalInvoices = hoaDons.size();
            double avgInvoice = totalInvoices > 0 ? totalRevenue / totalInvoices : 0;
            double serviceRevenue = hoaDonService.getTotalServiceRevenueByDateRange(startDate, endDate);

            lblTotalRevenue.setText(String.format("%,.0f đ", totalRevenue));
            lblTotalInvoices.setText(String.valueOf(totalInvoices));
            lblAverageInvoice.setText(String.format("%,.0f đ", avgInvoice));
            lblServiceRevenue.setText(String.format("%,.0f đ", serviceRevenue));

            // Update table
            tvHoaDon.getItems().clear();
            tvHoaDon.getItems().addAll(hoaDons);

            // Update chart
            updateRevenueChart(hoaDons);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void updateRevenueChart(List<HoaDonDTO> hoaDons) {
        chartRevenue.getData().clear();

        XYChart.Series<String, Number> series = new XYChart.Series<>();
        series.setName("Doanh Thu");

        // Group by date
        Map<LocalDate, Double> dailyRevenue = new TreeMap<>(
                hoaDons.stream()
                        .collect(Collectors.groupingBy(
                                HoaDonDTO::getNgayLap,
                                Collectors.summingDouble(HoaDonDTO::getTongTien)
                        ))
        );

        dailyRevenue.forEach((date, revenue) -> {
            series.getData().add(new XYChart.Data<>(date.toString(), revenue));
        });

        chartRevenue.getData().add(series);
    }

    private void applyCardStyle(VBox card) {
        DropShadow shadow = new DropShadow();
        shadow.setColor(Color.color(0, 0, 0, 0.05));
        shadow.setRadius(5);
        shadow.setOffsetY(2);
        card.setEffect(shadow);
    }

    private void showAlert(String title, String message) {
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setTitle(title);
        alert.setHeaderText(null);
        alert.setContentText(message);
        alert.show();
    }
}

